type ApiPayload = { error?: string; assets?: Asset[]; asset?: Asset; sources?: PublishedSource[]; dateFields?: GhlDateField[]; statusFields?: GhlStatusField[]; folders?: Folder[]; folder?: Folder; reusableBlocks?: ReusableBlock[]; reusableBlock?: ReusableBlock; data?: Draft; source?: { title: string; description: string; text: string }; submissions?: Submission[]; analytics?: Analytics; versions?: AssetVersion[]; executions?: Execution[]; submissionRetentionDays?: number | null; auditEvents?: AuditEvent[]; hasMoreAssets?: boolean; nextAssetOffset?: number | null };
