const contactFieldOptions = [["name", "Full name"], ["firstName", "First name"], ["lastName", "Last name"], ["email", "Email"], ["phone", "Phone"], ["companyName", "Company name"], ["address1", "Street address"], ["city", "City"], ["state", "County / region"], ["postalCode", "Eircode / postal code"]];
