  function addNode(type = "task") { patchDraft({ nodes: [...draft.nodes, { id: crypto.randomUUID().slice(0, 12), type, label: type === "wait" ? "Wait before next step" : type === "condition" ? "Check a condition" : type === "tag" ? "Update contact tag" : type === "updateContact" ? "Update GoHighLevel contact" : type === "customerEmail" ? "Email customer" : type === "customerSms" ? "Text customer" : type === "customerWhatsapp" ? "WhatsApp customer" : type === "end" ? "End workflow" : type === "stop" ? "Stop workflow" : "Create follow-up task", config: type === "wait" ? JSON.stringify({ amount: 5, unit: "minutes" }) : type === "condition" ? JSON.stringify({ fieldId: "", operator: "equals", value: "" }) : type === "tag" ? "add: New Lead" : type === "updateContact" ? JSON.stringify({ mappings: [{ fieldId: "", contactField: "" }] }) : ["customerEmail", "customerSms", "customerWhatsapp"].includes(type) ? JSON.stringify({ consentFieldId: "", ...(type === "customerEmail" ? { subject: "Thanks for getting in touch" } : {}), message: "Thanks {{name}}. We received your request and will be in touch." }, null, 2) : type === "end" || type === "stop" ? "" : "Follow up on new enquiry" }] }); }

