    try { const parsed = JSON.parse(draft.nodes[index]?.config || ""); config = parsed && typeof parsed === "object" ? parsed : { fieldId: String(draft.nodes[index]?.config || "").split("=")[0], operator: "equals", value: String(draft.nodes[index]?.config || "").split("=").slice(1).join("=") }; } catch { config = { fieldId: String(draft.nodes[index]?.config || "").split("=")[0], operator: "equals", value: String(draft.nodes[index]?.config || "").split("=").slice(1).join("=") }; }
