      <div className="marketing-builder-head"><div><h2>{name || `New ${labels[kind].slice(0, -1).toLowerCase()}`}</h2><small>{draftDirty ? busy ? "Saving…" : current ? "Unsaved changes · auto-save in a moment" : "Unsaved draft · save once to enable auto-save" : current ? `${current.status} · updated ${new Date(current.updatedAt).toLocaleString()}` : "Unsaved draft"}</small></div><div className="sites-heading-actions"><button type="button" className="secondary-button" onClick={undoDraft} disabled={busy || !draftHistory.past.length} aria-label="Undo last change">↶ Undo</button><button type="button" className="secondary-button" onClick={redoDraft} disabled={busy || !draftHistory.future.length} aria-label="Redo last change">↷ Redo</button><button className="secondary-button" onClick={() => void load()} disabled={busy}>↻ Refresh</button>{assetId && <button className="secondary-button" onClick={() => void remove()} disabled={busy}>Delete</button>}<button className="primary-button" onClick={() => void save(kind === "automation" && current?.status === "active" ? "active" : "draft")} disabled={busy}>{busy ? "Saving…" : kind === "automation" ? "Save workflow" : "Save draft"}</button>{kind !== "automation" && current?.hasPublishedVersion && <button type="button" className="secondary-button" onClick={unpublishCurrent} disabled={busy}>Unpublish</button>}{kind === "automation" && current?.status !== "active" && <button className="primary-button" onClick={() => void setAutomationStatus("active")} disabled={busy}>Activate internal workflow</button>}{kind === "automation" && current?.status === "active" && <button className="secondary-button" onClick={() => void setAutomationStatus("paused")} disabled={busy}>Pause workflow</button>}{kind !== "automation" && <button className="primary-button" onClick={() => void save("published")} disabled={busy}>{current?.status === "published" ? "Update published page" : "Publish"}</button>}</div></div>
      {kind === "automation" && automationEditorTab === "settings" && <section className="automation-editor-settings marketing-panel"><h3>Workflow settings</h3><p className="muted">Choose a clear name, the client this workflow belongs to, and the folder that keeps it organised.</p><div className="automation-settings-grid"><label className="field"><span>Workflow name</span><input value={name} onChange={(event) => updateProjectName(event.target.value)} maxLength={120} placeholder="e.g. New lead follow-up" /></label><label className="field"><span>Client</span><select value={clientId} onChange={(event) => updateClient(event.target.value)}><option value="">Workspace-level workflow</option>{clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select></label><label className="field"><span>Folder</span><select value={folderId} onChange={(event) => updateFolder(event.target.value)}><option value="">Unfiled</option>{folders.filter((folder) => folder.kind === "automation").map((folder) => <option key={folder.id} value={folder.id}>{folder.name}</option>)}</select></label></div><div className="automation-settings-status"><span className={`automation-status-pill ${current?.status || "draft"}`}>{current?.status === "active" ? "Published" : current?.status === "paused" ? "Paused" : "Draft"}</span><span>{current ? `Version ${current.version} · last updated ${new Date(current.updatedAt).toLocaleString("en-IE")}` : "Save this workflow once to enable automatic saving."}</span></div></section>}
